2-// picnic_table, rafter_tails. Each takes its position (and facing) as arguments and writes only into air, so it never
3-// replaces an earlier part's block or the ground. Two exceptions, both inside their own footprint: stair_run with
4-// { carve: true } clears headroom through a built floor, and kettle sinks its campfire into the y 0 surface.
5-// Every helper returns { placed, skipped }.
6-import { B, flight } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
7-
8-const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };
9-
10-const done = (w) => ({ placed: w.out.placed, skipped: w.out.skipped });
11-
12-// Air-only writes through g. over(x, y, z, block) lets a helper replace a non-air cell it owns; keep boxes are never
13-// written (openings and RESERVED cells). Returns get/set in the shape flight() writes through.
14-function writer(g, { over = () => false, keep = [] } = {}) {
15-  const out = { placed: 0, skipped: 0 };
16-  const kept = (x, y, z) => keep.some(([x0, y0, z0, x1, y1, z1]) => x >= x0 && x <= x1 && y >= y0 && y <= y1 && z >= z0 && z <= z1);
17-  const set = (x, y, z, block, state, nbt) => {
18-    const air = g.isAir(x, y, z);
19-    if (kept(x, y, z) || (!air && !over(x, y, z, block))) { out.skipped++; return false; }
20-    g.set(x, y, z, block, state, nbt);
21-    out.placed++;
22-    return true;
23-  };
24-  return { set, get: (x, y, z) => g.get(x, y, z), free: (x, y, z) => !kept(x, y, z) && g.isAir(x, y, z), out };
25-}
26-
27-// Fence connection flags as placement shows them: a side joins when a planned fence cell (keys "x,z", one row) is there.
28-const fenceFlags = (cells, x, z) => ({
29-  north: cells.has(`${x},${z - 1}`), south: cells.has(`${x},${z + 1}`),
30-  east: cells.has(`${x + 1},${z}`), west: cells.has(`${x - 1},${z}`),
31-});
--
