111-  const w = writer(g);
112-  if (g.isAir(x, y + 1, z)) return { placed: 0, skipped: 1 };
113-  const [block, , nbt] = B.sign(wood, String(text).split("\n"), { wall: false, hanging: true, rotation, dataVersion: g.dataVersion });
114-  w.set(x, y, z, block, { rotation: String(rotation), attached: "false" }, nbt);
