124-  w.set(x, 1, z, "water_cauldron", { level: "3" });
125-  return done(w);
126-}
127-
128-/** A picnic table: a spruce slab top (type top) across x..x+1, z..z+len-1 at y, with a spruce stair bench on each side
129- *  (x-1 facing west, x+2 facing east). Defaults match plot 6: picnic_table(g, 77, 11) with len 3 at y 1. */
130-export function picnic_table(g, x, z, len = 3, y = 1) {
131-  const w = writer(g);
